package io.github.ningpp.compat;

import java.io.InputStream;
import java.io.OutputStream;

/**
 * Replacement for System.Runtime.Serialization.Formatters.Binary.BinaryFormatter
 * (generated by CSharpToJava converter).
 *
 * <p>BinaryFormatter is permanently disabled in modern .NET: every
 * {@code Serialize}/{@code Deserialize} call throws
 * {@link PlatformNotSupportedException}. This shim reproduces that behaviour so
 * that the ported tests observe the same semantics they would on .NET Core /
 * .NET 5+.</p>
 */
public final class BinaryFormatter {

    private static final String DISABLED_MESSAGE =
            "BinaryFormatter serialization is obsolete and should not be used.";

    private Object surrogateSelector;
    private Object context;
    private FormatterAssemblyStyle assemblyFormat = FormatterAssemblyStyle.Simple;
    private TypeFilterLevel filterLevel = TypeFilterLevel.Full;
    private FormatterTypeStyle typeFormat = FormatterTypeStyle.TypesAlways;

    public BinaryFormatter() {
    }

    public BinaryFormatter(Object selector, Object context) {
        this.surrogateSelector = selector;
        this.context = context;
    }

    public Object getSurrogateSelector() {
        return surrogateSelector;
    }

    public void setSurrogateSelector(Object selector) {
        this.surrogateSelector = selector;
    }

    public Object getContext() {
        return context;
    }

    public void setContext(Object context) {
        this.context = context;
    }

    public FormatterAssemblyStyle getAssemblyFormat() {
        return assemblyFormat;
    }

    public void setAssemblyFormat(FormatterAssemblyStyle value) {
        this.assemblyFormat = value;
    }

    public TypeFilterLevel getFilterLevel() {
        return filterLevel;
    }

    public void setFilterLevel(TypeFilterLevel value) {
        this.filterLevel = value;
    }

    public FormatterTypeStyle getTypeFormat() {
        return typeFormat;
    }

    public void setTypeFormat(FormatterTypeStyle value) {
        this.typeFormat = value;
    }

    public void serialize(OutputStream stream, Object graph) {
        throw new PlatformNotSupportedException(DISABLED_MESSAGE);
    }

    /**
     * Overload accepting the compat MemoryStream type, which is not a
     * java.io.OutputStream subclass.
     */
    public void serialize(MemoryStream stream, Object graph) {
        throw new PlatformNotSupportedException(DISABLED_MESSAGE);
    }

    public Object deserialize(InputStream stream) {
        throw new PlatformNotSupportedException(DISABLED_MESSAGE);
    }

    /**
     * Overload accepting the compat MemoryStream type, which is not a
     * java.io.InputStream subclass.
     */
    public Object deserialize(MemoryStream stream) {
        throw new PlatformNotSupportedException(DISABLED_MESSAGE);
    }
}
